/*
 * A036584  Ternary Thue-Morse sequence: closed under a->abc, b->ac, c->b.
 * https://oeis.org/A036584
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn
 * Formula:   not stated
 * Range:     u8 n <= 2175, u16 n <= 10000, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   val_of_letter
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Ternary Thue‑Morse sequence generated by the substitutions
 *
 *   a → a b c
 *   b → a c
 *   c → b
 *
 * The sequence is returned as numbers 3, 1, 2 for a, b, c respectively.
 * The implementation keeps the length of each symbol after k substitutions
 * in three static tables, which grow only as deep as necessary for the
 * requested index.  No dynamic allocation of seq_t arrays is performed,
 * so it works with arbitrary‑precision seq_t types as well as with
 * integral ones.  Complexity is O(log n) per call. */

#include <stdint.h>
#include <stddef.h>
#include "../utils/val_of_letter.h"

/* ------------------------------------------------------------ */
/* static tables holding lengths a_len[k], b_len[k], c_len[k]    */
/* 64 levels are far more than enough for indices up to 10⁴      */
#define MAX_DEPTH 64
static seq_t a_len[MAX_DEPTH];
static seq_t b_len[MAX_DEPTH];
static seq_t c_len[MAX_DEPTH];
static size_t max_depth = 0;    /* first free slot (so a_len[0] valid) */
static int initialized = 0;     /* guard for one‑time initialisation   */
/* ------------------------------------------------------------ */

/* Initialise the length tables once.  The first level corresponds
 * to the single letters a, b, c themselves. */
static void init_tables(void)
{
    if (initialized)        /* already done */
        return;

    /* level 0: each symbol expands to itself – length 1 */
    a_len[0] = (seq_t)1;
    b_len[0] = (seq_t)1;
    c_len[0] = (seq_t)1;

    /* start with depth 1 (next free slot) */
    max_depth = 1;
    initialized = 1;
}

/* Ensure that we have enough levels so that a_len[max_depth-1] > n.
 * The tables are filled up to the required depth. */
static void ensure_depth(idx_t n)
{
    init_tables();  /* safety first */

    /* cast n to seq_t for comparisons */
    seq_t sn = (seq_t)n;

    while (max_depth > 0 && a_len[max_depth - 1] <= sn)
    {
        /* Compute next level lengths */
        /* a_{k+1} = a_k + b_k + c_k */
        /* b_{k+1} = a_k + c_k   */
        /* c_{k+1} = b_k         */
        a_len[max_depth] = a_len[max_depth - 1]
                           + b_len[max_depth - 1]
                           + c_len[max_depth - 1];
        b_len[max_depth] = a_len[max_depth - 1]
                           + c_len[max_depth - 1];
        c_len[max_depth] = b_len[max_depth - 1];

        ++max_depth;
    }
}

/* Main sequence function */
seq_t a(idx_t n)
{
    /* Make sure the length tables cover the required index */
    ensure_depth(n);

    /* Highest pre‑computed level that contains index n */
    size_t k = max_depth - 1;

    seq_t idx = (seq_t)n;   /* work in seq_t for safety */
    char cur = 'a';        /* start from the initial symbol */

    /* Walk from level k down to level 0, narrowing the index */
    while (k > 0) {
        if (cur == 'a') {
            seq_t l1 = a_len[k - 1];          /* length of a at level k-1 */
            seq_t l2 = b_len[k - 1];          /* length of b at level k-1 */
            seq_t l3 = c_len[k - 1];          /* length of c at level k-1 */

            if (idx < l1) {
                cur = 'a';
            } else if (idx < l1 + l2) {
                idx -= l1;
                cur = 'b';
            } else {
                idx -= l1 + l2;
                cur = 'c';
            }
        } else if (cur == 'b') {
            seq_t l1 = a_len[k - 1];
            seq_t l2 = c_len[k - 1];
            if (idx < l1) {
                cur = 'a';
            } else {
                idx -= l1;
                cur = 'c';
            }
        } else { /* cur == 'c' */
            seq_t l1 = b_len[k - 1];
            if (idx < l1) {
                cur = 'b';
            } /* else impossible, but we keep logic symmetrical */
        }
        --k;
    }

    return val_of_letter(cur);
}
